export const meta = {
  name: 'audio-lanes-r1',
  description: 'Road map audio round 1: litecode pipelines for AP1, AP9 and AP11 in three lanes, integrated one at a time',
  phases: [
    { title: 'Lane A', detail: 'AP1 loudness readout and Normalize to loudness' },
    { title: 'Lane B', detail: 'AP9 split edits (expected to STOP for the link model)' },
    { title: 'Lane C', detail: 'AP11 speech ducking and fade shapes (expected to STOP for where spans live)' },
  ],
}

const TEMPLATES = '/Users/kevingalligan/.claude-personal/skills/litecode/references/'
const I = '/Users/kevingalligan/devel/framejob/.claude/worktrees/audio-updates'
const HROOT = '/Users/kevingalligan/.claude/litecode/framejob/'
const COMMON = HROOT + 'audio-lanes-common.md'
const LOG = HROOT + 'audio-merges.log'
const DATE = '2026-10-30'

const LANES = [
  { lane: 'a', phase: 'Lane A', phases: [{ ap: 'AP1', dir: 'audio-ap1' }] },
  { lane: 'b', phase: 'Lane B', phases: [{ ap: 'AP9', dir: 'audio-ap9' }] },
  { lane: 'c', phase: 'Lane C', phases: [{ ap: 'AP11', dir: 'audio-ap11' }] },
]

const TRIAGE = { type: 'object', properties: { route: { type: 'string', enum: ['small', 'full'] }, summary: { type: 'string' } }, required: ['route', 'summary'] }
const DESIGN = { type: 'object', properties: { stop: { type: 'boolean' }, stop_reason: { type: 'string' }, summary: { type: 'string' } }, required: ['stop', 'summary'] }
const ADV = { type: 'object', properties: { verdict: { type: 'string' }, objections: { type: 'number' }, summary: { type: 'string' } }, required: ['verdict', 'objections', 'summary'] }
const BUILD = { type: 'object', properties: {
  status: { type: 'string', enum: ['done', 'stop'] }, stop_reason: { type: 'string' },
  base: { type: 'string', description: 'full sha of the integration HEAD your worktree started from (for a fixer: the base you were given)' },
  tip: { type: 'string', description: 'full sha of your last commit' },
  worktree: { type: 'string', description: 'absolute path of your worktree (pwd)' },
  branch: { type: 'string', description: 'git branch --show-current' },
  diff_lines: { type: 'number', description: 'total changed lines in git diff --stat base..tip' },
  checks_all_pass: { type: 'boolean' }, summary: { type: 'string' },
}, required: ['status', 'summary'] }
const REVIEW = { type: 'object', properties: {
  verdict: { type: 'string', enum: ['pass', 'fix-required'] },
  findings: { type: 'array', items: { type: 'string' }, description: 'blockers and should-fix, each "file:line — claim"' },
  summary: { type: 'string' },
}, required: ['verdict', 'findings', 'summary'] }
const INTEGRATE = { type: 'object', properties: {
  status: { type: 'string', enum: ['landed', 'failed', 'conflict-unresolved'] }, sha: { type: 'string' },
  filed: { type: 'array', items: { type: 'string' } }, detail: { type: 'string' },
}, required: ['status', 'detail'] }

let chain = Promise.resolve()
function locked(fn) { const run = chain.then(fn, fn); chain = run.then(() => {}, () => {}); return run }

function note(L, P) {
  return `LANE CONTEXT: road map "audio" ${P.ap}, lane ${L.lane.toUpperCase()}. Read ${COMMON} first: it is binding (the integration worktree ${I} is read-only to you unless you are the integrator; implementers and fixers work and commit in their own worktree, the current directory). Two other lanes run at the same time; never edit or build in another worktree, never touch /Users/kevingalligan/devel/framejob, kill only a Frame Job pid you launched.`
}

async function runPhase(L, P) {
  const H = HROOT + P.dir
  const opts = (stage, extra) => ({ label: `${P.ap} ${stage}`, phase: L.phase, ...extra })
  const stopped = (detail) => ({ ap: P.ap, status: 'stopped', detail })

  const tri = await agent(`Handoff dir: ${H}. Read request.md. Write 00-triage.md. ${note(L, P)}`, opts('triage', { agentType: 'lc-triage', schema: TRIAGE }))
  if (!tri) return { ap: P.ap, status: 'failed', detail: 'triage returned nothing' }
  log(`${P.ap}: triage → ${tri.route} route`)
  let specRef = 'request.md'
  if (tri.route === 'full') {
    const d1 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read request.md and 00-triage.md. Explore the repo as needed (read-only, in ${I}). Write 01-spec.md using the spec template. ${note(L, P)}`,
      opts('design', { agentType: 'lc-designer', schema: DESIGN }))
    if (!d1) return { ap: P.ap, status: 'failed', detail: 'designer returned nothing' }
    if (d1.stop) return stopped(d1.stop_reason || d1.summary)
    log(`${P.ap}: design done → adversary`)
    const adv = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md and only the files it names (in ${I}). Write 02-objections.md. ${note(L, P)}`,
      opts('adversary', { agentType: 'lc-adversary', schema: ADV }))
    if (adv && adv.objections === 0 && /proceed/.test(adv.verdict)) {
      const cp = await agent(`Copy ${H}01-spec.md to ${H}03-spec-final.md byte for byte (cp). Reply "done".`, opts('copy spec', { effort: 'low' }))
      specRef = '03-spec-final.md'
    } else {
      const d2 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md and 02-objections.md. Write 03-spec-final.md: the revised spec plus an "Objections addressed" section. If an objection exposes a choice only the owner can make, put STOP: <question, options, recommendation> at the top. ${note(L, P)}`,
        opts('final design', { agentType: 'lc-designer', schema: DESIGN }))
      if (!d2) return { ap: P.ap, status: 'failed', detail: 'final designer returned nothing' }
      if (d2.stop) return stopped(d2.stop_reason || d2.summary)
      specRef = '03-spec-final.md'
    }
    log(`${P.ap}: final spec → implement`)
  }

  const implPrompt = specRef === 'request.md'
    ? `Handoff dir: ${H}. Read request.md and 00-triage.md. No spec exists; implement the request directly, touching only files_likely_touched unless you justify otherwise in your notes. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first; commit your work in your worktree; return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
    : `Handoff dir: ${H}. Read ${specRef}. Implement it. Write 04-impl-notes.md and 04-checks.txt. ${note(L, P)} Record the base sha first (git rev-parse HEAD); commit your work in your worktree; return base, tip, worktree, branch. If you must stop, write STOP: <reason> at the top of 04-impl-notes.md and return status stop.`
  const impl = await agent(implPrompt, opts('implement', { agentType: 'lc-implementer', schema: BUILD, isolation: 'worktree' }))
  if (!impl) return { ap: P.ap, status: 'failed', detail: 'implementer returned nothing' }
  if (impl.status === 'stop') return { ...stopped(impl.stop_reason || impl.summary), worktree: impl.worktree, tip: impl.tip }
  const base = impl.base
  let tip = impl.tip
  let worktrees = [impl.worktree]
  log(`${P.ap}: implemented ${impl.diff_lines} lines (checks ${impl.checks_all_pass ? 'pass' : 'NOT all pass'}) at ${tip}`)
  const diffNote = () => `The git diff is \`git diff ${base}..${tip}\` (run it in ${I}; the refs are shared); the changed files are also readable under ${worktrees[worktrees.length - 1]}.`

  let reviewFile = null
  if (!(impl.diff_lines < 80 && impl.checks_all_pass)) {
    let rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, 04-impl-notes.md, 04-checks.txt, and the git diff. ${diffNote()} Write 05-review.md. ${note(L, P)}`,
      opts('review', { agentType: 'lc-reviewer', schema: REVIEW }))
    reviewFile = '05-review.md'
    let prev = []
    for (let pass = 1; rev && rev.verdict === 'fix-required'; pass++) {
      if (pass > 5) return { ap: P.ap, status: 'unresolved', detail: `unresolved after 5 fix passes: ${rev.findings.join(' | ')}`, tip, worktrees }
      const stuck = rev.findings.filter(f => prev.includes(f))
      if (pass > 1 && stuck.length) return { ap: P.ap, status: 'stuck', detail: `stuck findings: ${stuck.join(' | ')}`, tip, worktrees }
      prev = rev.findings
      const fx = await agent(`Handoff dir: ${H}. Read ${reviewFile} and the git diff. ${diffNote()} Your worktree is fresh: first \`git reset --hard ${tip}\`, then CoW-copy the build caches from ${worktrees[worktrees.length - 1]} as ${COMMON} says. Fix every blocker and should-fix. Re-run the spec's verification commands that your fixes can affect. Commit in your worktree. Write 06-fix-notes-${pass}.md. ${note(L, P)} Return base ${base} unchanged, your new tip, worktree and branch; status stop with STOP: at the top of the notes if you must stop.`,
        opts(`fix ${pass}`, { agentType: 'lc-fixer', schema: BUILD, isolation: 'worktree' }))
      if (!fx || fx.status === 'stop') return { ap: P.ap, status: 'stopped', detail: fx ? (fx.stop_reason || fx.summary) : 'fixer returned nothing', tip, worktrees }
      tip = fx.tip
      worktrees.push(fx.worktree)
      const next = `07-review-${pass + 1}.md`
      rev = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read ${specRef}, 04-impl-notes.md, 04-checks.txt, every 06-fix-notes-*.md so far, ${reviewFile}, and the git diff. ${diffNote()} Write ${next}. ${note(L, P)}`,
        opts(`re-review ${pass + 1}`, { agentType: 'lc-reviewer', schema: REVIEW }))
      reviewFile = next
    }
    if (!rev) return { ap: P.ap, status: 'failed', detail: 'reviewer returned nothing', tip, worktrees }
    log(`${P.ap}: review passed (${reviewFile})`)
  } else {
    log(`${P.ap}: review skipped (diff < 80 lines, checks pass)`)
  }

  const integ = await locked(() => agent(`You integrate one finished litecode phase of road map "audio" (${P.ap}) onto the integration branch. Integration worktree I=${I} (branch worktree-audio-updates); your shell starts there; run every command there with plain separate commands (the session refuses git aimed at another checkout). Handoff dir H=${H}. The phase's commits are ${base}..${tip} (shared refs); its worktrees: ${worktrees.join(', ')}.

Steps, in order:
1. Read H/${specRef}, H/04-impl-notes.md, H/04-checks.txt${reviewFile ? ', every H/06-fix-notes-*.md and H/' + reviewFile : ''}. Collect every "CLAUDE.md edits owed" item and every "To file" item.
2. \`git status --porcelain\` in I must be empty (else return failed). \`git cherry-pick --no-commit ${base}..${tip}\`. Resolve conflicts keeping both intents (other phases landed meanwhile: decision index rows and Lines cells, spec index cells, guide pages, catalogs, format version — if both bumped RC_FORMAT_VERSION, renumber this phase's to the next free number in format.rs, the header and its schema_vN.rs, and fix what reads it). If you cannot resolve one with confidence, \`git cherry-pick --abort\` and return conflict-unresolved naming the files.
3. Apply the CLAUDE.md edits owed in the files' own style (wrapped near 80 columns, rulebook prose, no status paragraphs).
4. Write the phase's record into I's designs/audio.md as a "### ${P.ap}'s record (${DATE})" section placed after the last existing "### AP…'s record" section: what landed (files, decisions AU-n0…), what was measured (numbers only as printed in the notes/checks), what the review found and how it was resolved, and what is owed (manual checks, To-file items). Keep it compact.
5. \`make gate\` in the foreground (Bash timeout 600000). If it fails because of the merge or steps 3–4, fix and re-run (at most two fixes); any other failure → return failed with the gate's last lines. If conflict resolution touched product code, re-run the phase's recorded proof against Release (RC_PROOF_APP=release) and record the result.
6. Stage everything the phase changed by explicit path (never FrameJob.xcodeproj, tools/proof/work/, tools/proof/media/, build products) and commit ONE commit: a subject saying what now works, ending "(road map audio ${P.ap})"; body: what changed, "Verified:" (the checks that passed incl. the Release proof and make gate), "Owed:" (or nothing); last line exactly: Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>.
7. Each "To file" item: \`gh issue create --label ai-drafted --label low-priority --title ... --body ...\` (body names the commit). Return them in filed.
8. Remove the phase's worktrees and branches: for each worktree path above, find its branch with \`git worktree list --porcelain\`, then \`git worktree remove --force <path>\` and \`git branch -D <branch>\`.
9. Append one line to ${LOG}: "${DATE} <short sha> ${P.ap} <subject>".
Never push, never touch /Users/kevingalligan/devel/framejob (main), never force-move a branch. Return the short sha.`,
    opts('integrate', { agentType: 'general-purpose', schema: INTEGRATE })))
  if (!integ) return { ap: P.ap, status: 'failed', detail: 'integrator returned nothing', tip, worktrees }
  if (integ.status !== 'landed') return { ap: P.ap, status: integ.status, detail: integ.detail, tip, worktrees }
  log(`${P.ap}: landed as ${integ.sha}`)
  return { ap: P.ap, status: 'landed', sha: integ.sha, filed: integ.filed || [], detail: integ.detail }
}

async function runLane(L) {
  phase(L.phase)
  const out = []
  for (let i = 0; i < L.phases.length; i++) {
    const r = await runPhase(L, L.phases[i])
    out.push(r)
    if (r.status !== 'landed') {
      for (const rest of L.phases.slice(i + 1)) out.push({ ap: rest.ap, status: 'not-run', detail: `lane halted at ${L.phases[i].ap}` })
      break
    }
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)

