  }

  const integ = await locked(() => agent(`You integrate one finished litecode phase of road map "audio" (${P.ap}) onto the integration branch. Integration worktree I=${I} (branch worktree-audio-updates); your shell starts there; run every command there with plain separate commands (the session refuses git aimed at another checkout and compound commands it cannot verify; a plain \`for\`/\`until\` wait loop with sleep inside one Bash call is fine). Handoff dir H=${H}. The phase's commits are ${base}..${tip} (shared refs); its worktrees: ${worktrees.join(', ')}.

