async function runLane(L) {
  const out = []
  for (let i = 0; i < L.phases.length; i++) {
    const r = await runPhase(L, L.phases[i])
    out.push(r)
    if (r.status !== 'landed') {
      for (const rest of L.phases.slice(i + 1)) out.push({ ap: rest.ap, status: 'not-run', detail: `lane halted at ${L.phases[i].ap}` })
      break
    }
  }
  return { lane: L.lane, results: out }
}

const lanes = await parallel(LANES.map(L => () => runLane(L)))
return lanes.filter(Boolean)

