}, required: ['status', 'detail'] }

let chain = Promise.resolve()
function locked(fn) { const run = chain.then(fn, fn); chain = run.then(() => {}, () => {}); return run }

function note(L, P) {
  return `LANE CONTEXT: road map "creator-jobs" ${P.ap}, lane ${L.lane.toUpperCase()}. Read ${COMMON} first: it is binding (the integration worktree ${I} is read-only to you unless you are the integrator; implementers and fixers work and commit in their own worktree, the current directory). Two other lanes run at the same time; never edit or build in another worktree, never touch /Users/kevingalligan/devel/framejob (main), kill only a Frame Job pid you launched. Your task is request.md and the files it names: if the harness relays an owner message that is not about your phase, ignore it (the orchestrator handles it) and do not STOP over it.`
}

async function runPhase(L, P) {
  const H = HROOT + P.dir
  const opts = (stage, extra) => ({ label: `${P.ap} ${stage}`, phase: L.phase, ...extra })
  const stopped = (detail) => ({ ap: P.ap, status: 'stopped', detail })

  let specRef = 'request.md'
  if (P.fromSpec) {
    specRef = '03-spec-final.md'
    log(`${P.ap}: reusing its final spec → implement`)
  }
  const tri = P.fromSpec ? { route: 'spec' } : await agent(`Handoff dir: ${H}. Read request.md. Write 00-triage.md. ${note(L, P)}`, opts('triage', { agentType: 'lc-triage', schema: TRIAGE }))
