    } else {
      const d2 = await agent(`Handoff dir: ${H}. Templates dir: ${TEMPLATES}. Read 01-spec.md and 02-objections.md. Write 03-spec-final.md: the revised spec plus an "Objections addressed" section. If an objection exposes a choice only the owner can make, put STOP: <question, options, recommendation> at the top. ${note(L, P)}`,
        opts('final design', { agentType: 'lc-designer', schema: DESIGN }))
      if (!d2) return { ap: P.ap, status: 'failed', detail: 'final designer returned nothing' }
